### Instruction:
Find the most frequent name in a given array of names.

### Input:
["John", "John", "Sandra", "Sandra", "Sandra", "Tom"]

### Response:
function mostFrequent(arr) {
    let maxCount = 0;
    let item;
    let frequencyMap = new Map();

    arr.forEach(name => {
        if (frequencyMap.has(name)) {
            frequencyMap.set(name, frequencyMap.get(name) + 1);
        } else {
            frequencyMap.set(name, 1);
        }
    });

    for (let [name, count] of frequencyMap.entries()) {
        if (count > maxCount) {
            maxCount = count;
            item = name;
        }
    }

    return item;
}

console.log(mostFrequent(["John", "John", "Sandra", "Sandra", "Sandra", "Tom"])); // Sandra

### Instruction:
Join two dictionaries by adding the values with the same key.

### Input:
d1 = {"a": 1, "b": 2, "c": 3}
d2 = {"a": 10, "d": 20, "e": 30}

### Response:
def join_dictionaries(d1, d2):
    ''' 
    This function joins two dictionaries by adding their values with
    the same key
    '''
    result = {}
    for k1, v1 in d1.items():
        result[k1] = v1

    for k2, v2 in d2.items():
        if k2 in result.keys():
            result[k2] += v2
        else:
            result[k2] = v2

    return result

if __name__ == '__main__':
    d1 = {"a": 1, "b": 2, "c": 3}
    d2 = {"a": 10, "d": 20, "e": 30}
    print(join_dictionaries(d1, d2))

