def intersect_dicts(d1, d2):
    """
    This function takes two dictionaries as input and returns a new dictionary that contains only the key-value pairs that are common to both dictionaries.
    """

### Solution:


    # Initialize an empty dictionary to store the intersection
    intersection = {}

    # Check if both input dictionaries are not empty
    if d1 and d2:

        # Iterate over the keys in the first dictionary
        for key in d1.keys():

            # Check if the key exists in the second dictionary
            if key in d2:

                # Check if the values associated with the key are equal
                if d1[key] == d2[key]:

                    # Add the key-value pair to the intersection dictionary
                    intersection[key] = d1[key]

    return intersection

