def combine_book_collections(collection1, collection2):
    """
    You are a librarian managing two book collections. Your task is to combine these collections into a single dictionary.
    However, there is one catch - if a book exists in both collections, you need to remove it from the final dictionary.

    Args:
    collection1 (dict): The first book collection.
    collection2 (dict): The second book collection.

    Returns:
    dict: The combined book collection without the books present in both collections.

    Example:
    combine_book_collections({"Book1": "Author1", "Book2": "Author2"}, {"Book2": "Author2", "Book3": "Author3"})
    Output: {"Book1": "Author1", "Book3": "Author3"}
    """

### Solution:


    combined_collection = {}

    for book, author in collection1.items():
        if book not in collection2:
            combined_collection[book] = author

    for book, author in collection2.items():
        if book not in collection1:
            combined_collection[book] = author

    return combined_collection
